  &reftitle.examples;

   Ejemplo con grapheme_strpos


<?php

$char_a_ring_nfd = "a\xCC\x8A";  // 'LATIN SMALL LETTER A WITH RING ABOVE' (U+00E5) forma normalizada "D"
$char_o_diaeresis_nfd = "o\xCC\x88"; // 'LATIN SMALL LETTER O WITH DIAERESIS' (U+00F6) forma normalizada "D"

print grapheme_strpos( $char_a_ring_nfd . $char_a_ring_nfd . $char_o_diaeresis_nfd, $char_o_diaeresis_nfd);

?>



  &example.outputs;


2



   Uso de la clave de configuración regional ks-identic para distinguir los selectores de variación

    Por defecto, los selectores de variación Unicode (U+FE0E texto, U+FE0F emoji) se ignoran
    durante la comparación. El uso de la clave de extensión de configuración regional ks-identic
    activa la ordenación de nivel idéntico, que los trata como caracteres distintos.



     El parámetro locale está disponible desde PHP 8.5.0.




<?php

$textStyle  = "\u{263A}\u{FE0E}"; // U+263A + U+FE0E (selector de presentación como texto)
$emojiStyle = "\u{263A}\u{FE0F}"; // U+263A + U+FE0F (selector de presentación como emoji)

// Configuración regional por defecto: los selectores de variación se ignoran, por lo que la aguja se encuentra en la posición 0.
var_dump(grapheme_strpos($textStyle, $emojiStyle));

// Con ks-identic: los selectores de variación son significativos, por lo que no hay coincidencia.
var_dump(grapheme_strpos($textStyle, $emojiStyle, 0, 'en_US-u-ks-identic'));

?>


